//! The Prisma plan and search against the upstream oracle.
//!
//! `crates/core/tests/prisma-oracle.json` is generated by
//! `script/prisma-oracle.mjs` from the upstream `prismaPlan`,
//! `getPrismaBonusMult` and `formulaEval`, so the Rust port is pinned to the
//! source of truth rather than to hand-picked numbers. The tiny save is
//! purpose-built for the status ladder and the ranking; the committed synthetic
//! account is the realistic run.

use idleon_core::model::{Control, Progress};
use idleon_core::prisma::{self, Outcome, Plan, Status};
use idleon_core::save::{Save, import};
use serde_json::Value;

fn oracle() -> Value {
    serde_json::from_str(include_str!("prisma-oracle.json")).expect("the oracle JSON is valid")
}

fn fixture() -> Save {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/data.json");
    let text = std::fs::read_to_string(path).expect("fixtures/data.json is committed");
    import(&text).expect("the fixture imports").save
}

fn tiny() -> Save {
    Save::new(
        serde_json::from_str(include_str!("prisma-save.json")).expect("the tiny save is valid"),
    )
}

fn status(id: &str) -> Status {
    match id {
        "ready" => Status::Ready,
        "already" => Status::Already,
        "ineligible" => Status::Ineligible,
        "unavailable" => Status::Unavailable,
        "unpurchased" => Status::Unpurchased,
        other => panic!("the oracle names an unknown status {other}"),
    }
}

fn number(value: &Value) -> Option<f64> {
    value.as_f64()
}

/// One save's plan, row for row, against its oracle block.
fn check_plan(save: &Save, expected: &Value) {
    let characters = expected["characters"].as_array().expect("characters");
    let multiplier = expected["multiplier"].as_f64().expect("the multiplier");
    for cauldron in 0..4 {
        let plan = prisma::plan(save, 0, cauldron).expect("the save plans");
        assert_eq!(
            plan.multiplier, multiplier,
            "cauldron {cauldron}: the Prisma multiplier"
        );
        assert_eq!(plan.characters.len(), characters.len());
        for (character, expected) in plan.characters.iter().zip(characters) {
            assert_eq!(character.name, expected["name"].as_str().expect("a name"));
            assert_eq!(
                character.class_name,
                expected["className"].as_str().expect("a class name"),
                "character {}",
                character.index
            );
        }
        let expected = &expected["cauldrons"][cauldron.to_string()];
        assert_eq!(plan.fragments, number(&expected["fragments"]), "fragments");
        assert_eq!(
            plan.map,
            number(&expected["map"]).map(|map| map as usize),
            "map"
        );
        let rows = expected["rows"].as_array().expect("rows");
        assert_eq!(plan.rows.len(), rows.len(), "cauldron {cauldron} rows");
        for (row, expected) in plan.rows.iter().zip(rows) {
            let id = expected["id"].as_str().expect("a row id");
            assert_eq!(row.id, id);
            assert_eq!(row.name, expected["name"].as_str().expect("a row name"));
            assert_eq!(row.effect, expected["effect"].as_str().expect("an effect"));
            assert_eq!(row.level, number(&expected["level"]), "{id}: level");
            assert_eq!(
                row.status,
                status(expected["status"].as_str().expect("a status")),
                "{id}: status"
            );
            assert_eq!(
                row.comparable,
                expected["comparable"].as_bool().expect("comparable"),
                "{id}: comparable"
            );
            assert_eq!(
                row.reason,
                expected["reason"].as_str().expect("a reason"),
                "{id}: reason"
            );
            let base = expected["base"].as_f64().expect("a base bonus");
            assert!(
                (row.bonus - base).abs() <= 1e-9,
                "{id}: the bubble bonus is {} here, upstream {base}",
                row.bonus
            );
            let with_prisma = expected["withPrisma"].as_f64().expect("a Prisma bonus");
            assert!(
                (row.with_prisma(plan.multiplier) - with_prisma).abs() <= 1e-9,
                "{id}: the Prisma bonus is {}, upstream {with_prisma}",
                row.with_prisma(plan.multiplier)
            );
        }
    }
}

fn run(plan: &Plan) -> Outcome {
    let mut report = |_progress: Progress| Control::Continue;
    prisma::run(plan, &mut report).expect("the run finishes")
}

#[test]
fn the_synthetic_account_plans_like_the_upstream_oracle() {
    let oracle = oracle();
    check_plan(&fixture(), &oracle["saves"]["fixture"]);
}

#[test]
fn the_tiny_save_covers_the_status_ladder_like_upstream() {
    let oracle = oracle();
    check_plan(&tiny(), &oracle["saves"]["tiny"]);
    let plan = prisma::plan(&tiny(), 0, 0).expect("the tiny save plans");
    assert_eq!(plan.comparable(), 2);
    assert_eq!(plan.rows.len(), 34);
    assert_eq!(plan.cauldron_label(), "Power");
}

#[test]
fn the_ranking_matches_the_upstream_bubble_bonus_order() {
    let plan = prisma::plan(&tiny(), 0, 0).expect("the tiny save plans");
    let outcome = run(&plan);
    // The oracle's bubble bonuses: 0:0 is Prisma-ed (10 -> 20), 0:2 is ready
    // (10 -> 20), so the bonus metric ranks both candidates by their change.
    let ranked: Vec<&str> = outcome
        .rank("bubble-bonus:0:2")
        .iter()
        .map(|result| result.row.id.as_str())
        .collect();
    assert_eq!(ranked, ["0:2", "0:0"]);
    let ready = outcome
        .results
        .iter()
        .find(|result| result.row.id == "0:2")
        .expect("the ready bubble");
    let change = ready.change("bubble-bonus:0:2").expect("the ready bonus");
    assert!((change.delta - 10.0).abs() <= 1e-9);
    assert_eq!(change.percent, Some(100.0));
    let already = outcome
        .results
        .iter()
        .find(|result| result.row.id == "0:0")
        .expect("the Prisma-ed bubble");
    let change = already
        .change("bubble-bonus:0:0")
        .expect("the retained bonus");
    assert!((change.delta + 10.0).abs() <= 1e-9);
    assert_eq!(change.percent, Some(-50.0));
}

#[test]
fn the_fixture_search_reports_every_comparable_bubble_and_its_coverage() {
    let plan = prisma::plan(&fixture(), 0, 0).expect("the fixture plans");
    let outcome = run(&plan);
    assert_eq!(outcome.results.len(), plan.comparable());
    assert!(
        outcome.results.len() > 20,
        "the fixture has most bubbles owned"
    );
    assert!(outcome.baseline.len() > 20);
    for result in &outcome.results {
        assert!(
            !result.changes.is_empty(),
            "{}: a comparison changes its bubble bonus",
            result.row.id
        );
        assert_eq!(result.changes.len(), 1);
    }
    assert_eq!(outcome.coverage.total(), outcome.coverage.total());
    assert_eq!(outcome.coverage.modelled(), 0);
    assert_eq!(outcome.coverage.missing(), outcome.coverage.total());
    assert!(
        outcome.coverage.total() >= 29,
        "the fixture carries many effects"
    );
}

#[test]
fn cancelling_a_run_hands_back_no_result() {
    let plan = prisma::plan(&fixture(), 0, 0).expect("the fixture plans");
    let mut seen = 0;
    let mut report = |_progress: Progress| {
        seen += 1;
        Control::Stop
    };
    assert!(
        prisma::run(&plan, &mut report).is_none(),
        "a cancelled run must not replace the result already on screen"
    );
    assert_eq!(seen, 1);
}
